begin;
create temporary table level_test(k text primary key,v uuid);
grant all on level_test to authenticated;
create function pg_temp.ok(value boolean,label text) returns void language plpgsql as $$ begin if value is distinct from true then raise exception 'FAIL: %',label; end if; end $$;
create function pg_temp.denied(statement text,label text) returns void language plpgsql as $$ begin begin execute statement; exception when insufficient_privilege or check_violation or raise_exception then return; end; raise exception 'FAIL (allowed): %',label; end $$;
insert into level_test values('admin',gen_random_uuid()),('editor',gen_random_uuid());
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_user_meta_data) select v,'authenticated','authenticated',v||'@example.test',now(),'{"display_name":"학교급 검증"}'::jsonb from level_test;
set local role authenticated;
select set_config('request.jwt.claim.sub',(select v::text from level_test where k='admin'),true);
insert into level_test values('elementary',public.create_school('가상 초등학교','서울','초등학교')),('middle',public.create_school('가상 중학교','서울')),('high',public.create_school('가상 고등학교','서울','고등학교'));
select pg_temp.ok((select school_type from public.workspaces where id=(select v from level_test where k='elementary'))='초등학교','elementary type persists');
select pg_temp.ok(private.workspace_grade_count((select v from level_test where k='high'))=3,'high school has three grades');
insert into level_test values('year_elementary',public.save_academic_year((select v from level_test where k='elementary'),2026,0,'[{"start_date":"2026-03-02","end_date":"2026-07-20"},{"start_date":"2026-08-17","end_date":"2027-02-28"}]',array[1,2,3,4,5,6]));
insert into level_test values('year_middle',public.save_academic_year((select v from level_test where k='middle'),2026,0,'[{"start_date":"2026-03-02","end_date":"2026-07-20"},{"start_date":"2026-08-17","end_date":"2027-02-28"}]',array[1,1,1]));
select pg_temp.ok((select count(*) from public.classes where workspace_id=(select v from level_test where k='elementary'))=21,'all six grade class counts saved');
select pg_temp.denied(format('select public.save_academic_year(%L,2026,1,%L::jsonb,array[1,1,1])',(select v from level_test where k='elementary'),'[{"start_date":"2026-03-02","end_date":"2026-07-20"},{"start_date":"2026-08-17","end_date":"2027-02-28"}]'),'elementary rejects three grade payload');
insert into public.events(workspace_id,academic_year_id,title,start_date,end_date,event_type,target_grades) values((select v from level_test where k='elementary'),(select v from level_test where k='year_elementary'),'6학년 일정','2026-11-09','2026-11-09','school',array[6]::smallint[]);
with x as(insert into public.subject_groups(workspace_id,name) values((select v from level_test where k='elementary'),'국어') returning id) insert into level_test select 'group',id from x;
with x as(insert into public.subjects(workspace_id,group_id,name) values((select v from level_test where k='elementary'),(select v from level_test where k='group'),'국어') returning id) insert into level_test select 'subject',id from x;
with x as(insert into public.curriculum_plans(workspace_id,cohort_year) values((select v from level_test where k='elementary'),2026) returning id) insert into level_test select 'plan',id from x;
select public.save_curriculum((select v from level_test where k='plan'),1,jsonb_build_array(jsonb_build_object('subject_id',(select v from level_test where k='subject'),'grade',6,'semester',2,'hours',34)));
select pg_temp.ok((select sum(hours) from public.curriculum_hours where plan_id=(select v from level_test where k='plan'))=34,'sixth grade curriculum saved');
select pg_temp.denied(format('select public.set_school_type(%L,''중학교'')',(select v from level_test where k='elementary')),'cannot discard upper grades by changing type');
select pg_temp.ok((select school_type from public.workspaces where id=(select v from level_test where k='elementary'))='초등학교','blocked change preserves type');
select public.set_school_type((select w.id from public.workspaces w where w.kind='personal'),'초등학교');
select pg_temp.ok((select school_type from public.workspaces where kind='personal')='초등학교','personal space supports school level');
reset role;
insert into public.workspace_members(workspace_id,user_id,role) values((select v from level_test where k='middle'),(select v from level_test where k='editor'),'editor');
set local role authenticated;
select set_config('request.jwt.claim.sub',(select v::text from level_test where k='editor'),true);
select pg_temp.denied(format('insert into public.events(workspace_id,academic_year_id,title,start_date,end_date,event_type,target_grades) values(%L,%L,''범위 밖'',''2026-11-09'',''2026-11-09'',''school'',array[4]::smallint[])',(select v from level_test where k='middle'),(select v from level_test where k='year_middle')),'editor cannot add fourth grade to middle school');
select pg_temp.denied(format('select public.set_school_type(%L,''초등학교'')',(select v from level_test where k='middle')),'editor cannot change school level');
reset role;
select 'School-level integration checks passed; synthetic data rolled back.' as result;
rollback;
